
#' Plot PSA Parameter Distribution Diagnostics
#'
#' Visualizes the agreement between theoretical probability
#' distributions and their Monte Carlo realizations.
#'
#' For each probabilistic parameter, a histogram of the simulated
#' values is compared with the corresponding theoretical
#' probability density function.
#'
#' The graphical presentation follows the unified CEAgroupR
#' conventions through the internal `ce_plot_base()` engine.
#'
#' @param x An object of class `cea_parameter_diagnostics`,
#'   generated by [compute_psa()].
#' @param ... Additional arguments (currently unused).
#'
#' @details
#' Original distribution specifications and simulated parameter
#' samples are retrieved from attributes of the diagnostic object.
#'
#' Histograms use 30 bins by default and are normalized to
#' probability density, allowing direct comparison with the
#' theoretical density curves.
#'
#' Supported distributions are normal, beta, gamma, lognormal,
#' and uniform.
#'
#' Each parameter is displayed in a separate panel with
#' independent horizontal and vertical scales.
#'
#' This graphical comparison is descriptive and does not
#' constitute a formal goodness-of-fit test.
#'
#' @return A `ggplot` object containing simulated histograms
#'   and theoretical probability density curves.
#'
#' @export
plot.cea_parameter_diagnostics <- function(x, ...) {

  # ============================================================
  # 1. Validate input
  # ============================================================

  if (!inherits(x, "cea_parameter_diagnostics")) {
    stop(
      "'x' must be a 'cea_parameter_diagnostics' object."
    )
  }

  distribution_specs <- attr(
    x,
    "distribution_specs"
  )

  parameter_samples <- attr(
    x,
    "parameter_samples"
  )

  if (is.null(distribution_specs) ||
      length(distribution_specs) == 0L) {
    stop(
      "Original distribution specifications are not ",
      "available in the diagnostic object."
    )
  }

  if (is.null(parameter_samples)) {
    stop(
      "Monte Carlo parameter samples are not ",
      "available in the diagnostic object."
    )
  }

  # ============================================================
  # 2. Theoretical density and quantile functions
  # ============================================================

  theoretical_density <- function(values, spec) {

    switch(
      spec$distribution,

      normal = stats::dnorm(
        values,
        mean = spec$mean,
        sd = spec$sd
      ),

      beta = stats::dbeta(
        values,
        shape1 = spec$shape1,
        shape2 = spec$shape2
      ),

      gamma = stats::dgamma(
        values,
        shape = spec$shape,
        rate = spec$rate
      ),

      lognormal = stats::dlnorm(
        values,
        meanlog = spec$meanlog,
        sdlog = spec$sdlog
      ),

      uniform = stats::dunif(
        values,
        min = spec$min,
        max = spec$max
      ),

      stop(
        "Unsupported probability distribution: ",
        spec$distribution
      )
    )
  }

  theoretical_quantiles <- function(probs, spec) {

    switch(
      spec$distribution,

      normal = stats::qnorm(
        probs,
        mean = spec$mean,
        sd = spec$sd
      ),

      beta = stats::qbeta(
        probs,
        shape1 = spec$shape1,
        shape2 = spec$shape2
      ),

      gamma = stats::qgamma(
        probs,
        shape = spec$shape,
        rate = spec$rate
      ),

      lognormal = stats::qlnorm(
        probs,
        meanlog = spec$meanlog,
        sdlog = spec$sdlog
      ),

      uniform = stats::qunif(
        probs,
        min = spec$min,
        max = spec$max
      ),

      stop(
        "Unsupported probability distribution: ",
        spec$distribution
      )
    )
  }

  # ============================================================
  # 3. Prepare simulated and theoretical data
  # ============================================================

  simulated_list <- list()
  theoretical_list <- list()
  parameter_labels <- character()

  for (parameter_name in names(distribution_specs)) {

    spec <- distribution_specs[[parameter_name]]

    if (!parameter_name %in% names(parameter_samples)) {
      stop(
        "Simulated samples not found for parameter: ",
        parameter_name
      )
    }

    samples <- parameter_samples[[parameter_name]]

    if (!is.numeric(samples) ||
        length(samples) == 0L ||
        any(!is.finite(samples))) {
      stop(
        "Invalid simulated values for parameter: ",
        parameter_name
      )
    }

    distribution_name <- switch(
      spec$distribution,
      normal = "Normal",
      beta = "Beta",
      gamma = "Gamma",
      lognormal = "Lognormal",
      uniform = "Uniform",
      spec$distribution
    )

    panel_label <- paste0(
      parameter_name,
      " (",
      distribution_name,
      ")"
    )

    parameter_labels <- c(
      parameter_labels,
      panel_label
    )

    # ----------------------------------------------------------
    # 3.1. Simulated observations
    # ----------------------------------------------------------

    simulated_list[[parameter_name]] <- data.frame(
      parameter = panel_label,
      value = samples,
      stringsAsFactors = FALSE
    )

    # ----------------------------------------------------------
    # 3.2. Theoretical density evaluation range
    # ----------------------------------------------------------

    quantiles <- theoretical_quantiles(
      c(0.001, 0.999),
      spec
    )

    x_range <- range(
      samples,
      quantiles,
      finite = TRUE
    )

    # Respect the theoretical support of bounded distributions
    if (spec$distribution == "beta") {
      x_range[1] <- max(0, x_range[1])
      x_range[2] <- min(1, x_range[2])
    }

    if (spec$distribution == "uniform") {
      x_range <- c(spec$min, spec$max)
    }

    x_grid <- seq(
      x_range[1],
      x_range[2],
      length.out = 512
    )

    density_values <- theoretical_density(
      x_grid,
      spec
    )

    theoretical_list[[parameter_name]] <- data.frame(
      parameter = panel_label,
      value = x_grid,
      density = density_values,
      stringsAsFactors = FALSE
    )
  }

  simulated_data <- dplyr::bind_rows(
    simulated_list
  )

  theoretical_data <- dplyr::bind_rows(
    theoretical_list
  )

  simulated_data$parameter <- factor(
    simulated_data$parameter,
    levels = parameter_labels
  )

  theoretical_data$parameter <- factor(
    theoretical_data$parameter,
    levels = parameter_labels
  )

  # ============================================================
  # 4. Initialize CEAgroupR graphical engine
  # ============================================================

  base <- ce_plot_base(
    data = simulated_data,
    color_by = "none",
    shape_by = "none",
    facet_by = "none",
    plot_by = NULL,
    palette = "Dark2"
  )

  theme_diagnostics <- base$plot$theme
  palette_values <- base$palette_values

  histogram_color <- palette_values[1]
  theoretical_color <- palette_values[2]

  # ============================================================
  # 5. Construct diagnostic plot
  # ============================================================

  p <- ggplot2::ggplot() +
    theme_diagnostics +

    # Simulated distribution
    ggplot2::geom_histogram(
      data = simulated_data,
      mapping = ggplot2::aes(
        x = .data[["value"]],
        y = ggplot2::after_stat(.data[["density"]])
      ),
      bins = 30,
      fill = histogram_color,
      colour = "white",
      alpha = 0.55,
      linewidth = 0.25,
      boundary = NULL,
      inherit.aes = FALSE
    ) +

    # Theoretical probability density
    ggplot2::geom_line(
      data = theoretical_data,
      mapping = ggplot2::aes(
        x = .data[["value"]],
        y = .data[["density"]]
      ),
      colour = theoretical_color,
      linewidth = 1,
      inherit.aes = FALSE
    ) +

    # Independent panels
    ggplot2::facet_wrap(
      ~ parameter,
      scales = "free"
    ) +

    # Numerical axis formatting
    ggplot2::scale_x_continuous(
      labels = scales::label_number()
    ) +
    ggplot2::scale_y_continuous(
      labels = scales::label_number()
    ) +

    # Labels
    ggplot2::labs(
      title = "PSA Parameter Distribution Diagnostics",
      subtitle = paste0(
        "Simulated histograms and theoretical densities (",
        nrow(parameter_samples),
        " Monte Carlo iterations)"
      ),
      x = "Parameter value",
      y = "Probability density"
    ) +

    ggplot2::theme(
      plot.title = ggplot2::element_text(
        face = "bold"
      ),
      strip.text = ggplot2::element_text(
        face = "bold"
      )
    )

  return(p)
}
